{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table maplemonk.easyecom_db_returns_intermediate as WITH FlattenedItems AS ( SELECT r.order_id, r.INVOICE_ID, r.REFERENCE_CODE, r.CREDIT_NOTE_ID, r.credit_note_number, r.ORDER_DATE::TIMESTAMP AS ORDER_DATE, r.INVOICE_DATE::TIMESTAMP AS INVOICE_DATE, r.RETURN_DATE::TIMESTAMP AS RETURN_DATE, r.MANIFEST_DATE::TIMESTAMP AS MANIFEST_DATE, r.IMPORT_DATE::TIMESTAMP AS IMPORT_DATE, r.LAST_UPDATE_DATE::TIMESTAMP AS LAST_UPDATE_DATE, r.MARKETPLACE, r.MARKETPLACE_ID, r.REPLACEMENT_ORDER, TRIM(ri.value:suborder_id::STRING, \'\"\') AS SUBORDER_ID, TRIM(ri.value:suborder_num::STRING, \'\"\') AS SALEORDERITEMCODE, TRIM(ri.value:company_product_id::STRING, \'\"\') AS COMPANY_PRODUCT_ID, TRIM(ri.value:productName::STRING, \'\"\') AS PRODUCTNAME, TRIM(ri.value:product_Id::STRING, \'\"\') AS PRODUCT_ID, TRIM(ri.value:sku::STRING, \'\"\') AS SKU, TRIM(ri.value:return_reason::STRING, \'\"\') AS RETURN_REASON, TRIM(ri.value:inventory_status::STRING, \'\"\') AS INVENTORY_STATUS, ri.value:returned_item_quantity::FLOAT AS RETURNED_QUANTITY, ri.value:credit_note_total_item_excluding_tax::FLOAT AS TOTAL_RETURN_AMOUNT_EXCL_TAX, ri.value:credit_note_total_item_tax::FLOAT AS RETURN_TAX, ri.value:credit_note_total_item_shipping_charge::FLOAT AS RETURN_SHIPPING_CHARGE, ri.value:credit_note_total_item_miscellaneous::FLOAT AS RETURN_MISC FROM maplemonk.easyecom_easyecom_emma_returns AS r, LATERAL FLATTEN(input => r.ITEMS) AS ri ) SELECT fi.*, COALESCE(fi.TOTAL_RETURN_AMOUNT_EXCL_TAX, 0) + COALESCE(fi.RETURN_TAX, 0) + COALESCE(fi.RETURN_SHIPPING_CHARGE, 0) + COALESCE(fi.RETURN_MISC, 0) AS TOTAL_RETURN_AMOUNT FROM FlattenedItems fi QUALIFY ROW_NUMBER() OVER ( PARTITION BY fi.REFERENCE_CODE, fi.SALEORDERITEMCODE ORDER BY fi.LAST_UPDATE_DATE DESC ) = 1; create or replace table emmasleep_db.maplemonk.emmasleep_db_returns_consolidated as with returns as ( select r.order_id , r.suborder_id , r.saleorderitemcode , r.reference_code , r.order_date , r.return_date , r.last_update_date , r.company_product_id , r.productname as product_name , r.product_id , r.sku , r.marketplace , r.marketplace_id , r.replacement_order , r.return_reason , CASE WHEN r.return_reason IN (\'Complaint - Wrong Variant \',\'Complaint-Wrong Product Ordered\',\'Complaint - Unknown\',\'Complaint - Quality Issue\',\'Damage in Transit\',\'Cancelled_after_invoice\',\'Not satisfied: Size issue\') THEN \'Customer Return\' ELSE \'Courier Return\' END AS return_type , CASE WHEN r.inventory_status IN (\'QC Pass\',\'Repair\') THEN \'Good Inventory\' ELSE \'Bad Inventory\' END AS inventory_type , r.total_return_amount , r.TOTAL_RETURN_AMOUNT_EXCL_TAX , r.RETURNED_QUANTITY from emmasleep_db.maplemonk.easyecom_db_returns_intermediate r ), sales as ( select s.quantity as order_quantity ,s.order_id ,s.marketplace ,s.channel as marketing_channel ,s.name as customer_name ,s.email as customer_email ,s.SHIPPING_LAST_UPDATE_DATE ,s.SHIPPING_STATUS ,s.SALEORDERITEMCODE ,replace(s.reference_code,\'#\',\'\') as reference_code ,s.DELIVERED_DATE ,s.return_flag ,s.returned_quantity ,s.returned_sales ,s.DAYS_IN_SHIPMENT ,s.CITY ,s.STATE ,s.pincode ,s.SELLING_PRICE ,s.discount ,s.order_date ,s.PRODUCT_NAME_final as product_name ,s.product_category ,s.PRODUCT_ID ,case when s.Payment_Mode in (\'ONLINE\',\'PREPAID\') THEN FALSE when s.Payment_Mode in (\'COD\') then TRUE else null end AS COD_Order , s.courier as Shipping_Courier , s.SKU , s.size , s.new_customer_flag , LAST_DAY(DATE(s.Order_Date),MONTH) AS MONTH FROM emmasleep_db.maplemonk.emmasleep_db_sales_consolidated s where lower(order_status) not like \'%cancel%\' qualify row_number() over (partition by reference_code,s.saleorderitemcode order by shipping_last_update_date desc) = 1 ) select s.month , s.order_quantity , s.product_name , s.product_category , s.size , s.sku , s.order_id , s.product_id , \'EMMA SLEEP\' as brand , CAST(s.order_date AS TIMESTAMP) as order_date , s.shipping_status , (case when c.order_item_status like \'%RETURN%\' then 1 when r.return_Date is not null then 1 else s.return_flag end) as return_flag , coalesce((case when lower(c.return_reason) like \'%rto%\' then \'Courier Return\' when not(c.return_reason is null) then \'Customer Return\' end),r.return_type) as return_type , r.inventory_type , r.return_date , r.last_update_date , coalesce(c.return_reason,r.return_reason) as return_reason , coalesce(r.total_return_amount,s.returned_sales,(case when c.order_item_status like \'%RETURN%\' then s.selling_price end)) as total_return_amount , r.replacement_order , coalesce(r.returned_quantity,s.returned_quantity) as returned_quantity , s.cod_order , s.selling_price , s.SALEORDERITEMCODE , s.reference_code , s.city , s.state , s.pincode , CASE WHEN s.pincode LIKE \'1%\' OR s.pincode LIKE \'2%\' THEN \'North Zone\' WHEN s.pincode LIKE \'3%\' OR s.pincode LIKE \'4%\' THEN \'West Zone\' WHEN s.pincode LIKE \'5%\' OR s.pincode LIKE \'6%\' THEN \'South Zone\' WHEN s.pincode LIKE \'7%\' OR s.pincode LIKE \'8%\' THEN \'East Zone\' ELSE NULL END AS zone , s.shipping_courier , s.customer_name , s.customer_email , s.new_customer_flag , s.marketing_channel , s.marketplace , coalesce(r.TOTAL_RETURN_AMOUNT_EXCL_TAX,ifnull(s.selling_price,0)/1.18) as TOTAL_RETURN_AMOUNT_EXCL_TAX from sales s left join returns r on r.saleorderitemcode = s.SALEORDERITEMCODE and r.reference_code = s.reference_code left join maplemonk.emmasleep_db__Product_Size_Mapping psm on lower(psm.sku) = lower(replace(s.sku,\'_Selfship\',\'\')) left join emmasleep_db.maplemonk.s3_flipkart_sales c on s.reference_code = c.ordeR_id and s.saleorderitemcode = replace(c.order_item_id,\'OI:\',\'\'); CREATE OR REPLACE TABLE maplemonk.emmasleep_db_returns_count_data as WITH orders as ( SELECT LAST_DAY(date(order_date), MONTH) as order_month, DATE_TRUNC(\'MONTH\', order_date) as month_first_date, date(order_date) as order_date, marketplace, count(distinct reference_code) as orders_for_the_month, COUNT(DISTINCT CASE WHEN (return_flag = 1) THEN reference_code END) AS total_returned_orders_for_orders_of_month, sum(case when (return_flag=1) then 1 else 0 end) as total_returned_items_for_orders_of_month, sum(case when (return_flag=1) then returned_quantity else 0 end) as total_returned_quantity_for_orders_of_month, count(*) as total_order_items_for_the_month, sum(order_quantity) as total_order_quantity_for_the_month, sum(selling_price) as total_sales FROM maplemonk.emmasleep_db_returns_consolidated GROUP BY order_month,month_first_date, order_date,marketplace ), returns as ( SELECT LAST_DAY(DATE(return_date), MONTH) as return_month, date(return_date) as return_date, marketplace, COUNT(*) as total_returned_items_received_in_month, count(distinct reference_code) as returned_orders_received_in_month, sum(returned_quantity) as returned_quantity_received_in_month, sum(TOTAL_RETURN_AMOUNT) as total_returned_sales FROM maplemonk.emmasleep_db_returns_consolidated WHERE return_flag = 1 GROUP BY return_month,return_date,marketplace ) SELECT o.month_first_date, o.marketplace, o.order_month, o.order_date, o.orders_for_the_month, o.total_order_items_for_the_month, o.total_order_quantity_for_the_month, o.total_returned_orders_for_orders_of_month, o.total_returned_items_for_orders_of_month, o.total_returned_quantity_for_orders_of_month, o.total_sales, r.total_returned_sales, r.return_date, r.total_returned_items_received_in_month, r.returned_orders_received_in_month, r.returned_quantity_received_in_month from orders o LEFT JOIN returns r ON r.return_date = o.order_date and r.marketplace = o.marketplace order by order_date desc;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from EMMASLEEP_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            